using System;using System.IO;using System.Linq;using System.Drawing;using System.Collections.Generic;using System.Globalization;using System.Diagnostics;using System.Threading.Tasks;using System.Windows.Forms;
namespace PCRecord {
 // Проверки кандидата релиза используют искусственное окно и подмену только показаний свободного места.
 internal static class ReleaseVerification {
  public static int Run(Paths p){int code=1;var rows=new List<object>();string folder=Path.Combine(p.Root,"verification");Directory.CreateDirectory(folder);
   using(var form=new TestPattern()){var media=new MediaTools(p);long free=10L*1024*1024*1024;var engine=new CaptureEngine(p,media,a=>form.BeginInvoke(a),()=>free);
    Func<string,Func<Task>,Task> check=async(name,action)=>{try{await action();rows.Add(Data.Map("test",name,"status","pass"));}catch(Exception ex){rows.Add(Data.Map("test",name,"status","failed","error",ex.ToString()));}Data.Write(Path.Combine(folder,"release-result.json"),Data.Map("running",true,"cases",rows));};
    form.Shown+=async(s,e)=>{try{await Task.Delay(1200);var config=Data.Map("kind","window","source",form.Handle.ToInt64().ToString(CultureInfo.InvariantCulture),"fps",30,"format","MP4","resolution","source","systemAudio",false,"microphone",false,"camera",false,"cursor",false,"clicks",true,"border",true,"toolbar",true);
     await check("countdown-cancel-without-capture",async()=>{var c=Copy(config);c["countdown"]=5;int before=Directory.GetFiles(p.Records).Length;var task=engine.Start(c,false);if(Data.Text(engine.Status(),"state")!="Countdown")throw new IOException("Нет состояния отсчёта");await Task.Delay(500);var result=await engine.Stop();await task;if(!Data.Flag(result,"cancelled")||engine.Busy||Directory.GetFiles(p.Records).Length!=before)throw new IOException("Отмена записала файл или оставила активный захват");});
     await check("three-second-countdown-real-capture",async()=>{var c=Copy(config);c["countdown"]=3;var sw=Stopwatch.StartNew();var task=engine.Start(c,false);await Task.Delay(2000);if(Data.Text(engine.Status(),"state")!="Countdown")throw new IOException("Захват начался до окончания отсчёта");await Wait(()=>Data.Text(engine.Status(),"state")=="Recording",12);if(sw.Elapsed.TotalSeconds<2.9)throw new IOException("Отсчёт слишком короткий");await Task.Delay(1600);var result=await engine.Stop();await task;await Decode(media,Data.Text(result,"path"));});
     foreach(string resolution in new[]{"720","1080"})await check("60fps-resolution-"+resolution,async()=>{var c=Copy(config);c["fps"]=60;c["resolution"]=resolution;var task=engine.Start(c,false);await Wait(()=>Data.Text(engine.Status(),"state")=="Recording",15);await Task.Delay(3200);var result=await engine.Stop();await task;var meta=await media.Probe(Data.Text(result,"path"));var stream=((System.Collections.IEnumerable)meta["streams"]).Cast<Dictionary<string,object>>().First(x=>Data.Text(x,"codec_type")=="video");if(Data.Num(stream,"width")!=(resolution=="720"?1280:1920)||Data.Num(stream,"height")!=(resolution=="720"?720:1080)||Data.Text(stream,"avg_frame_rate")!="60/1")throw new IOException("Неверные параметры видео");await Decode(media,Data.Text(result,"path"));rows.Add(Data.Map("test","metadata-"+resolution,"status","evidence","metadata",meta,"frames",Data.Get(result,"frames")));});
     await check("low-space-preflight-rejected",async()=>{free=100L*1024*1024;bool denied=false;try{await engine.Start(config,false);}catch(IOException){denied=true;}finally{free=10L*1024*1024*1024;}if(!denied)throw new IOException("Недостаток места не отклонён");});
     await check("low-space-during-recording-stop-and-decode",async()=>{var task=engine.Start(config,false);await Wait(()=>Data.Text(engine.Status(),"state")=="Recording",15);await Task.Delay(2000);free=32L*1024*1024;try{await Wait(()=>!engine.Busy,20);var result=await task;if(!Data.Text(engine.Status(),"warning").Contains("64"))throw new IOException("Нет предупреждения о свободном месте");await Decode(media,Data.Text(result,"path"));}finally{free=10L*1024*1024*1024;}});
     await check("closed-source-stop-and-decode",async()=>{using(var source=new TestPattern()){source.Text="PC Record — закрываемый источник";source.Show();await Task.Delay(500);var c=Copy(config);c["source"]=source.Handle.ToInt64().ToString(CultureInfo.InvariantCulture);var task=engine.Start(c,false);await Wait(()=>Data.Text(engine.Status(),"state")=="Recording",15);await Task.Delay(2000);source.Close();await Wait(()=>!engine.Busy,20);var result=await task;if(!Data.Text(engine.Status(),"warning").Contains("закрыто"))throw new IOException("Нет предупреждения о закрытом окне");await Decode(media,Data.Text(result,"path"));}});
     await check("suspend-notification-stops-and-decodes",async()=>{var task=engine.Start(config,false);await Wait(()=>Data.Text(engine.Status(),"state")=="Recording",15);await Task.Delay(1800);typeof(CaptureEngine).GetMethod("OnPowerModeChanged",System.Reflection.BindingFlags.NonPublic|System.Reflection.BindingFlags.Instance).Invoke(engine,new object[]{null,new Microsoft.Win32.PowerModeChangedEventArgs(Microsoft.Win32.PowerModes.Suspend)});await Wait(()=>!engine.Busy,20);var result=await task;if(!Data.Text(engine.Status(),"warning").Contains("приостанавливает"))throw new IOException("Нет предупреждения о приостановке");await Decode(media,Data.Text(result,"path"));});
     await check("simulated-timer-gap-stops-and-decodes",async()=>{var task=engine.Start(config,false);await Wait(()=>Data.Text(engine.Status(),"state")=="Recording",15);await Task.Delay(1800);typeof(CaptureEngine).GetField("lastSafetyUtc",System.Reflection.BindingFlags.NonPublic|System.Reflection.BindingFlags.Instance).SetValue(engine,DateTime.UtcNow.AddMinutes(-2));await Wait(()=>!engine.Busy,20);var result=await task;if(String.IsNullOrEmpty(Data.Text(engine.Status(),"warning")))throw new IOException("Нет предупреждения о разрыве времени");await Decode(media,Data.Text(result,"path"));});
     foreach(string item in new[]{"bad-fps","bad-countdown","missing-microphone","missing-camera","missing-loopback","outside-D","bad-format","double-start"})await check("reject-"+item,async()=>{bool denied=false;Task started=null;var c=Copy(config);try{switch(item){case "bad-fps":c["fps"]=17;break;case "bad-countdown":c["countdown"]=2;break;case "missing-microphone":c["microphone"]=true;c["micDevice"]="not-a-device";break;case "missing-camera":c["camera"]=true;c["cameraDevice"]="not-a-device";break;case "missing-loopback":c["systemAudio"]=true;c["loopback"]="not-a-device";break;case "outside-D":Paths.RequireD(@"C:\not-created");break;case "bad-format":c["format"]="BAD";break;case "double-start":c["countdown"]=5;started=engine.Start(c,false);break;}await engine.Start(c,false);}catch(IOException){denied=true;}if(engine.Busy)await engine.Stop();if(started!=null)await started;if(!denied)throw new IOException("Недопустимая операция разрешена");});
     await check("nan-trim-rejected",async()=>{var id=Directory.GetFiles(p.Records,"*.mp4").Select(Path.GetFileName).First();bool denied=false;try{await media.Trim(id,Double.NaN,1);}catch(IOException){denied=true;}if(!denied)throw new IOException("Граница NaN принята");});
     code=rows.OfType<Dictionary<string,object>>().Any(x=>Data.Text(x,"status")=="failed")?1:0;
    }catch(Exception ex){rows.Add(Data.Map("test","release-harness","status","failed","error",ex.ToString()));}finally{engine.Dispose();Data.Write(Path.Combine(folder,"release-result.json"),Data.Map("running",false,"cases",rows,"exitCode",code,"scope","Synthetic windows; fault injection changes only app-local free-space reading. No microphone or camera opened."));form.Close();}};Application.Run(form);
   }return code;
  }
  static Dictionary<string,object> Copy(Dictionary<string,object> c){return new Dictionary<string,object>(c);}
  static async Task Wait(Func<bool> ready,int seconds){var sw=Stopwatch.StartNew();while(!ready()){if(sw.Elapsed.TotalSeconds>seconds)throw new IOException("Истекло ожидание состояния");await Task.Delay(100);}}
  static Task<string> Decode(MediaTools media,string file){return media.Stream("ffmpeg.exe","-v error -xerror -i pipe:0 -f null -",file,null,45);}
 }
}
